package com.kazemieh.rasteh.marketplace.onboarding

import com.kazemieh.rasteh.identity.authorization.*
import com.kazemieh.rasteh.identity.membership.persistence.ShopMembershipRepository
import com.kazemieh.rasteh.identity.membership.persistence.entity.*
import com.kazemieh.rasteh.identity.persistence.UserRepository
import com.kazemieh.rasteh.marketplace.domain.*
import com.kazemieh.rasteh.marketplace.persistence.ShopRepository
import com.kazemieh.rasteh.marketplace.persistence.entity.ShopEntity
import com.kazemieh.rasteh.shared.error.*
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.OffsetDateTime
import java.util.UUID

data class ApplicationRequest(val idempotencyKey:String,val name:String,val phone:String?=null,val address:String?=null,val clusterId:UUID?=null,val buildingId:UUID?=null,val unitId:UUID?=null,val lat:Double?=null,val lng:Double?=null,val indoorX:Double?=null,val indoorY:Double?=null,val preciseLocationConsent:Boolean=false)
data class EvidenceRequest(val objectKey:String,val mediaType:String,val sha256:String,val retentionUntil:OffsetDateTime?=null)
data class ReviewApplicationRequest(val decision:ApplicationStatus,val reason:String?=null,val duplicateOfId:UUID?=null)

@Service class OnboardingService(private val applications:ShopApplicationRepository,private val evidence:ApplicationEvidenceRepository,private val claims:ShopClaimRepository,private val users:UserRepository,private val shops:ShopRepository,private val memberships:ShopMembershipRepository,private val auth:AuthorizationService,private val audit:OnboardingAuditRepository) {
 @Transactional fun draft(userId:Long,r:ApplicationRequest,agentId:Long?=null):ShopApplicationEntity { if(agentId!=null)auth.require(agentId,Capability.AGENT_DRAFT_WRITE); applications.findByApplicantUserIdAndIdempotencyKey(userId,r.idempotencyKey)?.let{return it}; validateCoordinates(r); val app=ShopApplicationEntity(applicantUserId=userId,agentUserId=agentId,name=r.name.trim(),normalizedName=norm(r.name),phone=r.phone?.trim(),normalizedPhone=r.phone?.let(::norm),address=r.address?.trim(),clusterId=r.clusterId,buildingId=r.buildingId,unitId=r.unitId,lat=r.lat,lng=r.lng,indoorX=r.indoorX,indoorY=r.indoorY,preciseLocationConsentedAt=if(r.preciseLocationConsent)OffsetDateTime.now()else null,idempotencyKey=r.idempotencyKey); return applications.save(app) }
 @Transactional fun consent(userId:Long,id:UUID):ShopApplicationEntity { val a=own(userId,id); if(a.status!=ApplicationStatus.DRAFT)deny("Application cannot be consented");a.status=ApplicationStatus.CONSENTED;a.preciseLocationConsentedAt=a.preciseLocationConsentedAt?:OffsetDateTime.now();return applications.save(a).also{log(it.id,userId,"APPLICATION_CONSENTED")} }
 @Transactional fun submit(userId:Long,id:UUID):ShopApplicationEntity { val a=own(userId,id);if(a.status!=ApplicationStatus.CONSENTED)deny("Consent is required before submission");val duplicates=applications.findAllByNormalizedNameAndNormalizedPhoneAndUnitId(a.normalizedName,a.normalizedPhone,a.unitId).filter{it.id!=a.id&&it.status !in setOf(ApplicationStatus.REJECTED,ApplicationStatus.CLOSED)};if(duplicates.isNotEmpty()){a.status=ApplicationStatus.NEEDS_CHANGES;a.duplicateOfId=duplicates.first().id;a.reviewReason="POSSIBLE_DUPLICATE"}else a.status=ApplicationStatus.SUBMITTED;return applications.save(a).also{log(it.id,userId,"APPLICATION_SUBMITTED")} }
 @Transactional fun review(reviewer:Long,id:UUID,r:ReviewApplicationRequest):ShopApplicationEntity { auth.require(reviewer,Capability.SHOP_APPLICATION_REVIEW);val a=applications.findById(id).orElseThrow{NotFoundException("Application not found","APPLICATION_NOT_FOUND")};if(reviewer==a.applicantUserId||reviewer==a.agentUserId)deny("Maker cannot review own application");if(a.status !in setOf(ApplicationStatus.SUBMITTED,ApplicationStatus.UNDER_REVIEW,ApplicationStatus.NEEDS_CHANGES))deny("Invalid review state");if(r.decision !in setOf(ApplicationStatus.UNDER_REVIEW,ApplicationStatus.NEEDS_CHANGES,ApplicationStatus.APPROVED,ApplicationStatus.REJECTED,ApplicationStatus.SUSPENDED))deny("Invalid review decision");a.status=if(r.decision==ApplicationStatus.APPROVED)ApplicationStatus.CLAIM_PENDING else r.decision;a.reviewReason=r.reason;a.duplicateOfId=r.duplicateOfId;a.reviewedByUserId=reviewer;a.reviewedAt=OffsetDateTime.now();return applications.save(a).also{log(it.id,reviewer,"APPLICATION_REVIEWED")} }
 @Transactional fun addEvidence(userId:Long,id:UUID,r:EvidenceRequest):ApplicationEvidenceEntity { own(userId,id);if(!r.objectKey.startsWith("private/"))throw BadRequestException("Evidence must use private object storage","EVIDENCE_PRIVATE_ONLY");return evidence.save(ApplicationEvidenceEntity(applicationId=id,objectKey=r.objectKey,mediaType=r.mediaType,sha256=r.sha256,retentionUntil=r.retentionUntil,uploadedByUserId=userId)).also{log(id,userId,"EVIDENCE_ADDED")} }
 fun evidenceFor(userId:Long,id:UUID):List<ApplicationEvidenceEntity>{val a=applications.findById(id).orElseThrow{NotFoundException("Application not found","APPLICATION_NOT_FOUND")};if(a.applicantUserId!=userId&&!auth.can(userId,Capability.SHOP_APPLICATION_REVIEW))deny("Evidence is private");return evidence.findAllByApplicationId(id)}
 @Transactional fun startClaim(userId:Long,id:UUID):ShopClaimEntity { val a=own(userId,id);if(a.status!=ApplicationStatus.CLAIM_PENDING)deny("Claim not available");return claims.findByApplicationId(id)?:claims.save(ShopClaimEntity(applicationId=id,claimantUserId=userId)) }
 @Transactional fun verifyClaimOtp(userId:Long,id:UUID,otp:String):ShopClaimEntity { val c=claims.findByApplicationId(id)?:throw NotFoundException("Claim not found","CLAIM_NOT_FOUND");if(c.claimantUserId!=userId)deny("Claim denied");val u=users.findById(userId).orElseThrow{NotFoundException("User not found","USER_NOT_FOUND")};if(u.otpCode!=otp||u.otpExpiry?.isBefore(OffsetDateTime.now())!=false)deny("OTP verification failed");c.status=ClaimStatus.VERIFIED;c.otpVerifiedAt=OffsetDateTime.now();return claims.save(c) }
 @Transactional fun approveClaim(reviewer:Long,id:UUID):ShopClaimEntity { auth.require(reviewer,Capability.SHOP_APPLICATION_REVIEW);val c=claims.findByApplicationId(id)?:throw NotFoundException("Claim not found","CLAIM_NOT_FOUND");val a=applications.findById(id).orElseThrow{NotFoundException("Application not found","APPLICATION_NOT_FOUND")};if(reviewer==c.claimantUserId||c.status!=ClaimStatus.VERIFIED)deny("Claim review denied");c.status=ClaimStatus.APPROVED;c.approvedByUserId=reviewer;c.approvedAt=OffsetDateTime.now();a.status=ApplicationStatus.ACTIVE; val owner=users.findById(c.claimantUserId).orElseThrow{NotFoundException("User not found","USER_NOT_FOUND")};val shop=shops.save(ShopEntity(owner=owner,name=a.name,phone=a.phone,address=a.address,status=ShopStatus.APPROVED,approvedAt=OffsetDateTime.now()));memberships.save(ShopMembershipEntity(shopId=shop.id,userId=owner.id,role=ShopMembershipRole.OWNER,status=MembershipStatus.ACTIVE,acceptedAt=OffsetDateTime.now()));applications.save(a);return claims.save(c) }
 fun queue(reviewer:Long,status:ApplicationStatus=ApplicationStatus.SUBMITTED):List<ShopApplicationEntity>{auth.require(reviewer,Capability.SHOP_APPLICATION_REVIEW);return applications.findAllByStatusOrderByIdDesc(status)}
 private fun own(userId:Long,id:UUID)=applications.findById(id).orElseThrow{NotFoundException("Application not found","APPLICATION_NOT_FOUND")}.also{if(it.applicantUserId!=userId)deny("Application denied")};private fun norm(v:String)=v.trim().lowercase().replace(Regex("\\s+")," ");private fun validateCoordinates(r:ApplicationRequest){if((r.lat==null)!=(r.lng==null)||(r.lat!=null&&(r.lat !in -90.0..90.0||r.lng!! !in -180.0..180.0)))throw BadRequestException("Invalid coordinates","INVALID_GEO");if((r.indoorX==null)!=(r.indoorY==null)||((r.indoorX!=null)&&r.unitId==null))throw BadRequestException("Indoor coordinate requires unit","INVALID_INDOOR_LOCATION")};private fun log(applicationId:UUID,actor:Long,action:String)=audit.save(OnboardingAuditEntity(applicationId=applicationId,actorUserId=actor,action=action));private fun deny(message:String):Nothing=throw ForbiddenException(message,"ONBOARDING_DENIED")
}
